(function () {
    "use strict";

    var STEP_ENDPOINT = "/api/v1/system/step";

    // Workload profiles generated by the backend (POST /api/v1/system/step with
    // workload_profile). Each click uses the next profile so all four
    // classes are exercised; the backend builds the processes and their features.
    var WORKLOAD_PROFILES = ["cpu_bound", "io_bound", "priority_critical", "balanced"];
    var nextProfile = Math.floor(Math.random() * WORKLOAD_PROFILES.length);

    function buildStepRequest() {
        var profile = WORKLOAD_PROFILES[nextProfile];
        nextProfile = (nextProfile + 1) % WORKLOAD_PROFILES.length;
        return { workload_profile: profile, num_processes: 4 + Math.floor(Math.random() * 5) };
    }

    function setStepFeedback(text, state) {
        var el = document.getElementById("step-feedback");
        if (!el) {
            return;
        }
        el.textContent = text || "";
        el.classList.remove("is-error", "is-ok");
        if (state) {
            el.classList.add("is-" + state);
        }
    }

    function readError(response) {
        return response.json().then(
            function (body) {
                return (body && body.error) || "Request failed (" + response.status + ")";
            },
            function () {
                return "Request failed (" + response.status + ")";
            }
        );
    }

    function initStepSystem() {
        var stepBtn = document.getElementById("step-system-btn");
        if (!stepBtn) {
            return;
        }
        var label = stepBtn.querySelector(".btn-label");

        stepBtn.addEventListener("click", function (event) {
            event.preventDefault();
            if (stepBtn.disabled) {
                return;
            }

            stepBtn.disabled = true;
            stepBtn.setAttribute("aria-busy", "true");
            if (label) {
                label.textContent = "Running…";
            }
            setStepFeedback("", null);

            fetch(STEP_ENDPOINT, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Accept: "application/json"
                },
                body: JSON.stringify(buildStepRequest())
            })
                .then(function (response) {
                    if (!response.ok) {
                        return readError(response).then(function (message) {
                            throw new Error(message);
                        });
                    }
                    return response.json();
                })
                .then(function (record) {
                    var stepNo = typeof record.step_index === "number" ? record.step_index + 1 : null;
                    setStepFeedback(stepNo !== null ? "Step " + stepNo + " complete" : "Step complete", "ok");
                    document.dispatchEvent(new CustomEvent("system:stepped", { detail: record }));
                })
                .catch(function (error) {
                    var message = error && error.message ? error.message : "Request failed";
                    if (error instanceof TypeError) {
                        message = "Backend unreachable. Is the server running?";
                    }
                    setStepFeedback("Step failed: " + message, "error");
                    document.dispatchEvent(new CustomEvent("system:step-failed", { detail: { message: message } }));
                })
                .then(function () {
                    stepBtn.disabled = false;
                    stepBtn.removeAttribute("aria-busy");
                    if (label) {
                        label.textContent = "Step System";
                    }
                });
        });
    }

    function initResetSystem() {
        var resetBtn = document.getElementById("reset-system-btn");
        if (!resetBtn) {
            return;
        }
        resetBtn.addEventListener("click", function (event) {
            event.preventDefault();
            if (resetBtn.disabled) {
                return;
            }
            if (!window.confirm("Reset the system? This clears the step history and the failed-request log, and starts again from step 1.")) {
                return;
            }
            resetBtn.disabled = true;
            fetch("/api/v1/system/reset", { method: "POST", headers: { Accept: "application/json" } })
                .then(function (response) {
                    if (!response.ok) {
                        return readError(response).then(function (message) {
                            throw new Error(message);
                        });
                    }
                    window.location.reload();
                })
                .catch(function (error) {
                    var message = error instanceof TypeError ? "Backend unreachable. Is the server running?" : error.message;
                    setStepFeedback("Reset failed: " + message, "error");
                    resetBtn.disabled = false;
                });
        });
    }

    function initNavKeyboardAccessibility() {
        var navLinks = document.querySelectorAll(".nav-link");
        if (!navLinks.length) {
            return;
        }

        navLinks.forEach(function (link) {
            link.addEventListener("focus", function () {
                link.classList.add("is-focused");
            });

            link.addEventListener("blur", function () {
                link.classList.remove("is-focused");
            });
        });
    }

    function initSafeFormDefaults() {
        var forms = document.querySelectorAll("form[data-prevent-default]");
        if (!forms.length) {
            return;
        }

        forms.forEach(function (form) {
            form.addEventListener("submit", function (event) {
                event.preventDefault();
            });
        });
    }

    // Tracks whether the backend is reachable. Every page fetches its own data,
    // so wrapping fetch once here lets all pages show the same banner when the
    // server goes away and hide it again when a request succeeds.
    function initConnectionBanner() {
        if (typeof window.fetch !== "function") {
            return;
        }
        var originalFetch = window.fetch.bind(window);
        var lastOk = null;
        var banner = null;

        function formatTime(date) {
            return date.toLocaleTimeString();
        }

        function ensureBanner() {
            if (banner) {
                return banner;
            }
            banner = document.createElement("div");
            banner.className = "connection-banner";
            banner.setAttribute("role", "alert");
            banner.hidden = true;
            document.body.insertBefore(banner, document.body.firstChild);
            return banner;
        }

        function showDown() {
            var el = ensureBanner();
            el.textContent = lastOk
                ? "Backend unreachable. Showing data from " + formatTime(lastOk) + ", which may be out of date."
                : "Backend unreachable. No data has loaded yet.";
            el.hidden = false;
        }

        function showUp() {
            lastOk = new Date();
            if (banner) {
                banner.hidden = true;
            }
        }

        window.fetch = function (input) {
            var url = typeof input === "string" ? input : (input && input.url) || "";
            var isApi = url.indexOf("/api/") !== -1;
            var promise = originalFetch.apply(null, arguments);
            if (isApi) {
                promise.then(
                    function (response) {
                        if (response.status >= 500 && response.status !== 503) {
                            showDown();
                        } else {
                            showUp();
                        }
                    },
                    showDown
                );
            }
            return promise;
        };
    }

    // Header status chip ("Operational" / "Degraded" / "Critical" and "Last updated").
    // It lives in base.html, so it is driven from here on every page: fetched on
    // load, after each step and every 30 seconds while the tab is visible. The
    // Overview page already fetches the same data, so it claims the chip and
    // feeds it through window.ResourceHeader.apply() instead of a second request.
    var STATUS_ENDPOINT = "/api/v1/monitor/overview";
    var STATUS_POLL_MS = 30000;

    function initHeaderStatus() {
        var claimed = false;
        var inFlight = false;

        function setState(label, state) {
            var header = document.getElementById("hero-status");
            var el = document.getElementById("system-health-value");
            if (el) {
                el.textContent = label;
            }
            if (header && state) {
                header.classList.remove("hero-status--ok", "hero-status--warn", "hero-status--critical");
                header.classList.add("hero-status--" + state);
            }
        }

        function apply(data) {
            if (!data) {
                return;
            }
            var status = data.status;
            if (status === "ok") {
                setState("Operational", "ok");
            } else if (status === "warn" || status === "warning" || status === "degraded") {
                setState("Degraded", "warn");
            } else if (status === "critical" || status === "error" || status === "down") {
                setState("Critical", "critical");
            } else {
                setState(status ? String(status) : "Unknown", "ok");
            }
            var updated = document.getElementById("last-updated-value");
            if (updated) {
                var date = data.timestamp ? new Date(data.timestamp) : null;
                updated.textContent = !date ? "—" : (isNaN(date.getTime()) ? String(data.timestamp) : date.toLocaleString());
            }
        }

        function error() {
            setState("Unreachable", "critical");
        }

        function loading() {
            setState("Loading…", null);
        }

        function refresh() {
            if (inFlight) {
                return;
            }
            inFlight = true;
            fetch(STATUS_ENDPOINT, { headers: { Accept: "application/json" } })
                .then(function (response) {
                    if (!response.ok) {
                        throw new Error("Status request failed (" + response.status + ")");
                    }
                    return response.json();
                })
                .then(apply, error)
                .then(function () {
                    inFlight = false;
                });
        }

        window.ResourceHeader = {
            apply: apply,
            error: error,
            loading: loading,
            refresh: refresh,
            claim: function () {
                claimed = true;
            }
        };

        // Deferred so a page script initialised in the same tick can claim the chip first.
        setTimeout(function () {
            if (!claimed) {
                loading();
                refresh();
            }
        }, 0);
        document.addEventListener("system:stepped", function () {
            if (!claimed) {
                refresh();
            }
        });
        setInterval(function () {
            if (!document.hidden) {
                refresh();
            }
        }, STATUS_POLL_MS);
        document.addEventListener("visibilitychange", function () {
            if (!document.hidden) {
                refresh();
            }
        });
    }

    function init() {
        initConnectionBanner();
        initHeaderStatus();
        initStepSystem();
        initResetSystem();
        initNavKeyboardAccessibility();
        initSafeFormDefaults();
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", init);
    } else {
        init();
    }
})();